mapper.select:
select us.RYBM,us.XM as NAME,z.DZZDM as PARTYCODE,z.DZZMC as PARTYNAME, u.JOINUSERID,u.FLOWID,u.FLOWNAME,u.PFLOWID,u.PFLOWNAME,u.SORT,ifnull(u.lateDays,0) as lateDays,ifnull(u.PROGRESS,0) as PROGRESS, ryzt.hzmc as RYZTMC from VM_RYJBXX_ALL us inner join ZZ_ZZQKXX z on us.SZDZBDM=z.DZZDM left join Zzzd_ryzt ryzt on us.ryzt=ryzt.bm -- 人员状态 left join ( select u.JOINUSERID,u.USERCODE,nowflow.lateDays,nowflow.FLOWID,nowflow.FLOWNAME,nowflow.PFLOWNAME,nowflow.PARENTID as PFLOWID, nowflow.SORT,(ifnull(nowflow.PROGRESS,0)*100) as PROGRESS from PE_JOINUSER u left join ( select usernow.JOINUSERID, p.FLOWNAME as PFLOWNAME,f.PARENTID,f.FLOWNAME,f.FLOWID,uf.ACCOMPLISHTIME,usernow.SORT, nextflow.FLOWID as next_flowid,nextflow.FLOWNAME as next_flowname,nextflow.SORT as next_sort, (case when nextflow.WARNDAYS is null then 0 when (sysdate() - warn.ACCOMPLISHTIME) > nextflow.WARNDAYS then (sysdate() - warn.ACCOMPLISHTIME) - nextflow.WARNDAYS else 0 end) as lateDays, round(usernow.SORT/25,4) as PROGRESS from ( select uf.JOINUSERID,max(f.SORT) as SORT from PE_JOINUSER_FLOW uf inner join PE_FLOW f on uf.FLOWID = f.FLOWID where uf.OPERATESTATE not in ('D') group by uf.JOINUSERID ) usernow -- 当前环节 inner join PE_FLOW f on usernow.SORT = f.SORT and f.PARENTID is not null inner join PE_FLOW p on f.PARENTID = p.FLOWID inner join PE_JOINUSER_FLOW uf on f.FLOWID = uf.FLOWID and usernow.JOINUSERID = uf.JOINUSERID and uf.OPERATESTATE not in ('D') left join PE_FLOW nextflow on (f.SORT+1)=nextflow.SORT and nextflow.PARENTID is not null left join PE_JOINUSER_FLOW warn on nextflow.WARNUPFLOWID = warn.FLOWID and usernow.JOINUSERID = warn.JOINUSERID and warn.OPERATESTATE not in ('D') order by usernow.JOINUSERID ) nowflow on u.JOINUSERID= nowflow.JOINUSERID ) u on us.RYBM=u.USERCODE where 1=1 and (us.RYZT in('1','2','5','6') or (us.RYZT='3' and u.USERCODE is not null))
and u.JOINUSERID =#{id}
and u.lateDays>0
and (u.lateDays <= 0 or u.lateDays is null)
and us.SZDZBDM like concat( '%',#{partyCode},'%')
and us.xm like concat('%',#{name},'%')
and u.flowId =#{flowId}
and u.pflowid in
#{flowId}
and u.SORT >= #{beginSort}
and u.SORT <= #{endSort}
and us.RYZT in
#{ryzt}
order by ifnull(u.lateDays,0) desc,us.XMPY,us.RYJBXXBS

select us.RYBM,us.XM as NAME,z.DZZDM as PARTYCODE,z.DZZMC as PARTYNAME, u.JOINUSERID,u.FLOWID,u.FLOWNAME,u.PFLOWID,u.PFLOWNAME,u.SORT,ifnull(u.lateDays,0) as lateDays,ifnull(u.PROGRESS,0) as PROGRESS, ryzt.hzmc as RYZTMC from VM_RYJBXX_ALL us inner join ZZ_ZZQKXX z on us.SZDZBDM=z.DZZDM left join Zzzd_ryzt ryzt on us.ryzt=ryzt.bm -- 人员状态 left join ( select u.JOINUSERID,u.USERCODE,nowflow.lateDays,nowflow.FLOWID,nowflow.FLOWNAME,nowflow.PFLOWNAME,nowflow.PARENTID as PFLOWID, nowflow.SORT,(ifnull(nowflow.PROGRESS,0)*100) as PROGRESS from PE_JOINUSER u left join ( select usernow.JOINUSERID, p.FLOWNAME as PFLOWNAME,f.PARENTID,f.FLOWNAME,f.FLOWID,uf.ACCOMPLISHTIME,usernow.SORT, nextflow.FLOWID as next_flowid,nextflow.FLOWNAME as next_flowname,nextflow.SORT as next_sort, (case when nextflow.WARNDAYS is null then 0 when (sysdate - warn.ACCOMPLISHTIME) > nextflow.WARNDAYS then (sysdate - warn.ACCOMPLISHTIME) - nextflow.WARNDAYS else 0 end) as lateDays, round(usernow.SORT/25,4) as PROGRESS from ( select uf.JOINUSERID,max(f.SORT) as SORT from PE_JOINUSER_FLOW uf inner join PE_FLOW f on uf.FLOWID = f.FLOWID where uf.OPERATESTATE not in ('D') group by uf.JOINUSERID ) usernow --当前环节 inner join PE_FLOW f on usernow.SORT = f.SORT and f.PARENTID is not null inner join PE_FLOW p on f.PARENTID = p.FLOWID inner join PE_JOINUSER_FLOW uf on f.FLOWID = uf.FLOWID and usernow.JOINUSERID = uf.JOINUSERID and uf.OPERATESTATE not in ('D') left join PE_FLOW nextflow on (f.SORT+1)=nextflow.SORT and nextflow.PARENTID is not null left join PE_JOINUSER_FLOW warn on nextflow.WARNUPFLOWID = warn.FLOWID and usernow.JOINUSERID = warn.JOINUSERID and warn.OPERATESTATE not in ('D') order by usernow.JOINUSERID ) nowflow on u.JOINUSERID= nowflow.JOINUSERID ) u on us.RYBM=u.USERCODE where 1=1 and us.RYZT in('1','2','5','6')
and u.JOINUSERID =#{id}
and u.lateDays>0
and (u.lateDays <= 0 or u.lateDays is null)
and us.SZDZBDM like concat( '%',#{partyCode},'%')
and us.xm like concat('%',#{name},'%')
and u.flowId =#{flowId}
and u.pflowid in
#{flowId}
and u.SORT >= #{beginSort}
and u.SORT <= #{endSort}
and us.RYZT in
#{ryzt}
and us.SZDZBDM = #{szdzbdm}
order by ifnull(u.lateDays,0) desc,us.XMPY,us.RYJBXXBS
